-- ===== ข้อมูลตั้งต้นจาก Google Maps (ดึงผ่าน Apify เมื่อ 26 ต.ค. 2569) =====
-- หอพัก 90 แห่ง และร้านอาหาร 198 ร้าน ในรัศมี 2 กม. จากวิทยาลัย
-- ค่าห้อง ประเภทหอ ห้องว่าง ช่วงราคา และเมนู ยังว่างอยู่ ทีมกรอกเพิ่มผ่านหน้าแอดมิน
-- รูปเก็บไว้ในโฟลเดอร์ img/places ของเว็บ (ภาพจาก Google Maps)
-- ไฟล์นี้เก็บไว้เป็นหลักฐานว่านำเข้าอะไรไปบ้าง รันซ้ำได้ (google_place_id ซ้ำจะถูกข้าม)

-- ลบข้อมูลตัวอย่าง (สมมติ) ชุดเดิม รีวิวของข้อมูลตัวอย่างถูกลบตามไปด้วย (on delete cascade)
delete from public.dorms where name like 'หอพักตัวอย่าง %';
delete from public.restaurants where name like 'ร้าน%ตัวอย่าง %';

on conflict (google_place_id) do nothing;

on conflict (google_place_id) do nothing;
